#include <array>
#include <cstddef>
#include <iostream>
int main() {
    const std::array<std::size_t, 3> free_sizes{30, 18, 24};
    const std::size_t request = 16;
    std::size_t first = free_sizes.size();
    std::size_t best = free_sizes.size();
    for (std::size_t i = 0; i < free_sizes.size(); ++i) {
        if (free_sizes[i] < request) continue;
        if (first == free_sizes.size()) first = i;
        if (best == free_sizes.size() || free_sizes[i] < free_sizes[best]) best = i;
    }
    if (first == free_sizes.size() || best == free_sizes.size()) return 1;
    std::cout << "first fit=" << free_sizes[first]
              << " remainder=" << free_sizes[first]-request << '\n';
    std::cout << "best fit=" << free_sizes[best]
              << " remainder=" << free_sizes[best]-request << '\n';
}

#include <algorithm>
#include <array>
#include <cstddef>
#include <iostream>
struct Region { std::size_t bytes; bool free; };
std::size_t largest_run(const std::array<Region, 3>& regions) {
    std::size_t run = 0, largest = 0;
    for (const auto region : regions) {
        run = region.free ? run + region.bytes : 0;
        largest = std::max(largest, run);
    }
    return largest;
}
int main() {
    // Model: these three 8-byte regions are physically consecutive.
    std::array<Region, 3> regions{{{8,true}, {8,false}, {8,true}}};
    std::cout << "free total=16 largest=" << largest_run(regions) << '\n';
    std::cout << std::boolalpha << "12-byte request fits="
              << (largest_run(regions) >= 12) << '\n';
    regions[1].free = true;
    std::cout << "after middle release largest=" << largest_run(regions) << '\n';
    std::cout << "12-byte request fits=" << (largest_run(regions) >= 12) << '\n';
}

