// LAB: Build a bounded aligned arena model
// Implement reserve_bytes(used,capacity,request) for eight-byte-aligned starts. Return no start on failure and leave used unchanged. This models offsets, not actual object construction.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <cstddef>
#include <iostream>

int main() {
    const std::size_t capacity = 32;
    std::size_t used = 0;
    for (std::size_t request : {5u, 9u}) {
        const std::size_t start = (used + 7) / 8 * 8;
        assert(start <= capacity && request <= capacity - start);
        std::cout << start << ' ';
        used = start + request;
    }
    std::cout << "used=" << used << '\n';
}

#include <cassert>
#include <cstddef>
#include <iostream>
#include <optional>

std::optional<std::size_t> reserve_bytes(std::size_t& used, std::size_t capacity,
                                        std::size_t request) {
    if(used > capacity) return std::nullopt;
    const auto padding = (8 - used%8)%8;
    if(padding > capacity-used) return std::nullopt;
    const auto start = used+padding;
    if(request > capacity-start) return std::nullopt;
    used = start+request;
    return start;
}

int main() {
    std::size_t used = 0;
    const auto first = reserve_bytes(used,32,5);
    const auto second = reserve_bytes(used,32,9);
    assert(first == 0 && second == 8 && used == 17);
    const auto before = used;
    assert(!reserve_bytes(used,32,20) && used == before);
    std::cout << "starts=" << *first << ',' << *second << " used=" << used << '\n';
}

